import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { act, render, screen } from '@testing-library/react';

// SFCC-863 — the whole point of this suite: DntNotification (Salesforce's placeholder
// consent-tracking modal, real Lorem ipsum body copy, no config flag to disable it) must never
// render. Mocked with spies rather than simply left unmocked so a future regression (an
// upstream sync re-adding the import/hook-call/JSX this story removed) is actually caught —
// an unmocked, unimported dependency would make this suite pass trivially either way.
const useDntNotification = vi.fn(() => ({ isOpen: false, onOpen: vi.fn(), onClose: vi.fn() }));
const DntNotification = vi.fn((props: unknown) => (
  <div data-testid="dnt-notification-placeholder" data-props={JSON.stringify(props)}>
    Lorem ipsum
  </div>
));
vi.mock('@salesforce/retail-react-app/app/hooks/use-dnt-notification', () => ({
  useDntNotification: () => useDntNotification(),
  DntNotification: (props: unknown) => DntNotification(props),
}));

// Everything below is mocked at the smallest surface needed to render App's tree without
// crashing — per testing.md, each dependency's own behaviour is already covered by its own
// suite (Header/Footer/DrawerMenu/ListMenu each have their own index.test.tsx; the base SFCC
// hooks are Salesforce's own tested code). This suite asserts only App's own contract: that it
// no longer wires up DntNotification, and that the sibling AuthModal survived the edit intact.
// A stable object reference (not a new literal per call) — matches real react-router-dom's
// useLocation, which returns the same identity across re-renders unless the URL actually
// changes. Needed for the SFCC-885 suite below: a fresh object every render would make App's
// pre-existing "close the drawer on location change" effect (see index.tsx's own comment)
// re-fire on every re-render, fighting the breakpoint-close assertions before they can run.
const mockLocation = { pathname: '/', search: '' };
vi.mock('react-router-dom', () => ({
  useHistory: () => ({ push: vi.fn() }),
  useLocation: () => mockLocation,
}));
// Subpath export — not resolvable under Vitest without an explicit mock (see testing.md's
// ZimmIcon gap for the same subpath-resolution shape of problem).
vi.mock('@salesforce/commerce-sdk-react/components', () => ({
  StorefrontPreview: ({ children }: { children: React.ReactNode }) => <>{children}</>,
}));
vi.mock('@salesforce/pwa-kit-react-sdk/ssr/universal/utils', () => ({
  getAssetUrl: (path: string) => `/mocked/${path}`,
  getRouterBasePath: () => '',
}));
vi.mock('@salesforce/retail-react-app/app/hooks/use-active-data', () => ({
  default: () => ({ trackPage: vi.fn() }),
}));
vi.mock('@salesforce/retail-react-app/app/contexts', () => ({
  CurrencyProvider: ({ children }: { children: React.ReactNode }) => <>{children}</>,
}));
vi.mock('@tanstack/react-query', () => ({
  useQuery: () => ({ data: {} }),
}));
vi.mock('@salesforce/commerce-sdk-react', () => ({
  useAccessToken: () => ({ getTokenWhenReady: vi.fn() }),
  useCategory: () => ({ data: undefined }),
  useShopperBasketsMutation: () => ({ mutate: vi.fn() }),
  useUsid: () => ({ usid: 'test-usid' }),
}));
vi.mock('@salesforce/pwa-kit-react-sdk/ssr/universal/hooks', () => ({
  useServerContext: () => ({ req: undefined }),
}));
vi.mock('@salesforce/pwa-kit-runtime/utils/ssr-config', () => ({
  getConfig: () => ({ app: { storeLocatorEnabled: false, commerceAgent: undefined } }),
}));
vi.mock('@salesforce/retail-react-app/app/hooks/use-app-origin', () => ({
  useAppOrigin: () => 'https://test.zimmermann.com',
}));
vi.mock('@salesforce/retail-react-app/app/utils/logger-instance', () => ({
  default: { warn: vi.fn() },
}));
vi.mock('@salesforce/retail-react-app/app/components/_app/partials/above-header', () => ({
  default: () => null,
}));
// Spy on DrawerMenu's own isOpen/onClose props — the SFCC-885 suite below asserts on these
// directly rather than any rendered DOM, since the real DrawerMenu is mocked out here (its own
// suite already covers its rendering; see testing.md's mock-the-smallest-surface guidance).
const drawerMenuSpy = vi.fn();
vi.mock('../drawer-menu', () => ({
  DrawerMenu: (props: { isOpen?: boolean; onClose?: () => void }) => {
    drawerMenuSpy(props);
    return null;
  },
}));
vi.mock('../footer', () => ({ default: () => <div data-testid="footer-stub" /> }));
// Captures the real onMenuClick (App's onOpen from useDisclosure) so the SFCC-885 suite below
// can open the drawer the same way LeftBar's hamburger would, without needing the real Header.
let capturedOnMenuClick: (() => void) | undefined;
vi.mock('../header', () => ({
  default: ({ children, onMenuClick }: { children: React.ReactNode; onMenuClick?: () => void }) => {
    capturedOnMenuClick = onMenuClick;
    return <div data-testid="header-stub">{children}</div>;
  },
}));
vi.mock('@salesforce/retail-react-app/app/components/island', () => ({
  default: ({ children }: { children: React.ReactNode }) => <>{children}</>,
}));
vi.mock('../list-menu', () => ({ ListMenu: () => null, ListMenuContent: () => null }));
vi.mock('@salesforce/retail-react-app/app/components/offline-banner', () => ({ default: () => null }));
vi.mock('@salesforce/retail-react-app/app/components/offline-boundary', () => ({
  default: ({ children }: { children: React.ReactNode }) => <>{children}</>,
}));
vi.mock('../responsive', () => ({
  HideOnDesktop: ({ children }: { children: React.ReactNode }) => <>{children}</>,
  HideOnMobile: () => null,
  MOBILE_DESKTOP_SPLIT: 'md',
}));
vi.mock('@salesforce/retail-react-app/app/components/scroll-to-top', () => ({ default: () => null }));
vi.mock('@salesforce/retail-react-app/app/components/store-locator', () => ({ StoreLocatorModal: () => null }));
vi.mock('@salesforce/retail-react-app/app/pages/checkout/partials/checkout-footer', () => ({ default: () => null }));
vi.mock('@salesforce/retail-react-app/app/pages/checkout/partials/checkout-header', () => ({ default: () => null }));
vi.mock('@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal', () => ({
  AddToCartModalProvider: ({ children }: { children: React.ReactNode }) => <>{children}</>,
}));
vi.mock('@salesforce/retail-react-app/app/hooks/use-auth-modal', () => ({
  AuthModal: () => <div data-testid="auth-modal-stub" />,
  useAuthModal: () => ({ isOpen: false }),
}));
vi.mock('@salesforce/retail-react-app/app/hooks/use-bonus-product-selection-modal', () => ({
  BonusProductSelectionModalProvider: ({ children }: { children: React.ReactNode }) => <>{children}</>,
}));
vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
  useCurrentBasket: () => ({ data: undefined, dataUpdatedAt: 0 }),
}));
