import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { COUNTRIES, DEFAULT_COUNTRY_SLUG, type CountryConfig } from '../config/countries';

type MultiSiteContext = {
  site?: { id: string; alias?: string };
  locale?: { id: string; preferredCurrency?: string };
};

/**
 * Returns the full CountryConfig for the active SFCC site + locale.
 *
 * Matches on both sfccSiteId and locale to disambiguate the en-GB collision
 * between the UK site ('gb') and EU English ('eu'). Falls back to AU when the
 * site ID is unrecognised (e.g. during local dev before config/sites.js is wired up).
 *
 * @returns The CountryConfig for the current region, or the AU default.
 */
export function useCountryConfig(): CountryConfig {
  const { site, locale } = useMultiSite() as MultiSiteContext;
  const match = Object.values(COUNTRIES).find((c) => c.sfccSiteId === site?.id && c.locale === locale?.id);
  return match ?? COUNTRIES[DEFAULT_COUNTRY_SLUG];
}
