import { useWishlistAuthDrawer } from 'app/hooks/useWishlistAuthDrawer';

export type ZimmWishlistAuthDrawerProps = {
  /**
   * Called after successful passwordless/OTP login. Not invoked for IDP (Apple/Google)
   * flows — those trigger a full browser redirect; the user lands back already logged in.
   */
  onAuthSuccess?: () => void;
  /** Identifies this mounted instance so a social-IDP round-trip resumes the right
   *  `onAuthSuccess` — required because more than one instance (e.g. header + PDP) can be
   *  mounted on the page the shopper returns to. Stable per call site, e.g. `'header-wishlist'`
   *  or `'pdp-wishlist'` — see `useWishlistAuthDrawer`'s own doc comment. */
  intentId: string;
  /** The single trigger element (button, icon-button, etc.). Its onClick is replaced by the
   *  auth-gate handler — call the original action via onAuthSuccess instead. */
  children: React.ReactElement;
};

/**
 * Organism — wraps a single trigger element and gates its action behind auth.
 * If the customer is already registered the original onClick fires immediately.
 * If not, the Zimmermann auth drawer opens instead (passwordless email + optional social IDPs).
 *
 * Drop-in replacement for `withRegistration(Button)` on wishlist-specific entry points.
 * All SDK and auth logic lives in `useWishlistAuthDrawer` — this component is purely presentational.
 */
export const ZimmWishlistAuthDrawer = ({ onAuthSuccess, intentId, children }: ZimmWishlistAuthDrawerProps) => {
  const {
    isOpen,
    handleDrawerClose,
    handleTriggerClick,
    triggerRef,
    drawerTitle,
    description,
    emailValue,
    onEmailChange,
    onSendCode,
    onSignInWithApple,
    onSignInWithGoogle,
    isSocialEnabled,
    isPasswordlessEnabled,
    emailInputRef,
    onCreateAccount,
    isOtpAuthOpen,
    onOtpAuthClose,
    form,
    handlePasswordlessLogin,
    handleOtpVerification,
    registerModal,
  } = useWishlistAuthDrawer({ onAuthSuccess, intentId });

  return (
    <>
      {React.cloneElement(React.Children.only(children), { onClick: handleTriggerClick })}
      <ZimmDrawer
        isOpen={isOpen}
        onClose={handleDrawerClose}
        size="small"
        title={drawerTitle}
        finalFocusRef={triggerRef}
        initialFocusRef={emailInputRef}
      >
        <ErrorFallback>
          <ZimmAuthDrawerContent
            description={description}
            emailValue={emailValue}
            onEmailChange={onEmailChange}
            onSendCode={onSendCode}
            onSignInWithApple={onSignInWithApple}
            onSignInWithGoogle={onSignInWithGoogle}
            onCreateAccount={onCreateAccount}
            socialEnabled={isSocialEnabled}
            passwordlessEnabled={isPasswordlessEnabled}
            initialFocusRef={emailInputRef}
          />
        </ErrorFallback>
      </ZimmDrawer>
      <AuthModal {...registerModal} />
      <OtpAuth
        isOpen={isOtpAuthOpen}
        onClose={onOtpAuthClose}
        form={form}
        handleSendEmailOtp={handlePasswordlessLogin}
        handleOtpVerification={handleOtpVerification}
