import { afterEach, beforeEach, describe, test, expect, vi } from 'vitest';
import { resolveBackgroundColour, resolveBorderColour, resolveTextColour, ZimmSizeChip } from './zimmSizeChip.css';

/**
 * The Figma state cascade (disabled > selected > default) is the part of this recipe that can
 * break without surfacing as a type or build error — a mis-ordered branch renders a
 * plausible-but-wrong colour. `index.test.tsx` mocks `useMultiStyleConfig` globally, so these
 * resolvers are never exercised by any shipped component test; these assertions are the only
 * thing that actually calls them. Mirrors zimmTextInput.css.test.ts's pattern for the same class
 * of untested-resolver gap.
 */

// .claude/rules/testing.md asks for beforeEach setup and vi.clearAllMocks() after each test.
// The resolvers here are pure and this file mocks nothing, so these hooks are a convention
// baseline rather than load-bearing isolation — kept so the file matches the rule as written
// and stays correct if a mock is ever introduced.

/**
 * Matches zimmSizeChip.css.ts's own (module-private, deliberately not re-exported)
 * ZimmSizeChipStyleProps shape structurally — TypeScript's structural typing means this file
 * doesn't need that type exported to pass a compatible object literal to the resolvers.
 */
type SizeChipStyleProps = {
  selected?: boolean;
  disabled?: boolean;
};

let base: SizeChipStyleProps;

beforeEach(() => {
  base = { selected: false, disabled: false };
});

afterEach(() => {
  vi.clearAllMocks();
});

describe('ZimmSizeChip — border colour precedence', () => {
  test('default: neither selected nor disabled has no box (transparent border)', () => {
    expect(resolveBorderColour(base)).toBe('transparent');
  });

  test('selected (not disabled) uses the focus border colour — outline-only box', () => {
    expect(resolveBorderColour({ ...base, selected: true })).toBe('var(--zimm-color-border-focus)');
  });

  test('disabled (not selected) has no box (transparent border)', () => {
    expect(resolveBorderColour({ ...base, disabled: true })).toBe('transparent');
  });

  test('disabled wins over selected — no box, not the selected outline', () => {
    expect(resolveBorderColour({ ...base, selected: true, disabled: true })).toBe('transparent');
  });
});

describe('ZimmSizeChip — background colour precedence', () => {
  test('default: neither selected nor disabled is transparent', () => {
    expect(resolveBackgroundColour(base)).toBe('transparent');
  });

