import React, { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { chakra } from '@chakra-ui/react';
import { expect, userEvent, waitForElementToBeRemoved, within } from 'storybook/test';
import { ZimmDrawer } from './index';
import type { ZimmDrawerSize } from './index';

const meta: Meta<typeof ZimmDrawer> = {
  title: 'Elements/ZimmDrawer',
  component: ZimmDrawer,
};
export default meta;
type Story = StoryObj<typeof ZimmDrawer>;

/**
 * Generic chrome only — no tab/header content here (see Commerce/ZimmPdpDrawer for a real
 * consumer). Proves the shell renders with the expected dialog semantics at each size variant.
 */
// Named component rather than an inline `render: () => { useState(...) }` — see zimmModal's
// story for why a lowercase `render` can't call hooks directly.
const OpenDrawerExample = ({ size }: { size: ZimmDrawerSize }) => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmDrawer isOpen={isOpen} onClose={() => setIsOpen(false)} size={size} aria-label="Example drawer">
      <chakra.p padding="var(--zimm-scale-xl)">Generic ZimmDrawer chrome with arbitrary children.</chakra.p>
    </ZimmDrawer>
  );
};

export const Large: Story = {
  render: () => <OpenDrawerExample size="large" />,
  play: async () => {
    // Portal renders outside canvasElement — testing.md §Layer-2 exception. Chakra's Drawer is
    // built on its Modal primitive, which renders DrawerContent via a Portal by default, so
    // within(canvasElement) can't reach it.
    const doc = within(document.body);
    const dialog = await doc.findByRole('dialog');
    await expect(dialog).toBeInTheDocument();
    await expect(dialog).toHaveAttribute('aria-label', 'Example drawer');
  },
};

export const Tablet: Story = {
  render: () => <OpenDrawerExample size="tablet" />,
};

export const Small: Story = {
  render: () => <OpenDrawerExample size="small" />,
};

export const XLarge: Story = {
  render: () => <OpenDrawerExample size="xLarge" />,
};

export const Mobile: Story = {
  render: () => <OpenDrawerExample size="mobile" />,
};

export const CloseButtonClosesTheDrawer: Story = {
  render: () => <OpenDrawerExample size="large" />,
  play: async () => {
    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see Large's play).
    const doc = within(document.body);
    const dialog = await doc.findByRole('dialog');
    await expect(dialog).toBeInTheDocument();

    await userEvent.click(doc.getByRole('button', { name: /close/i }));

    // Chakra's Drawer plays a slide-out exit transition (framer-motion) before AnimatePresence
    // actually unmounts the dialog node — an immediate `queryByRole('dialog')` assertion here
    // catches it mid-animation, still present with a near-100% translateX. Wait for the real
    // removal instead of asserting the instant after the click.
    await waitForElementToBeRemoved(dialog);
  },
};

